<?php
declare(strict_types=1);
require_once dirname(__DIR__).'/app/bootstrap.php';require_login();$pdo=db();$p=(string)($_GET['p']??'dashboard');
function all(PDO $p,string $q,array $a=[]):array{$s=$p->prepare($q);$s->execute($a);return $s->fetchAll();}function val(PDO $p,string $q,array $a=[]):mixed{$s=$p->prepare($q);$s->execute($a);return $s->fetchColumn();}
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();try{$a=$_POST['action']??'';
 if($a==='stok_giris'){$mid=(int)$_POST['malzeme_id'];$did=(int)$_POST['depo_id'];$lot=trim((string)$_POST['lot_no']);$skt=$_POST['skt']?:null;$q=(float)$_POST['miktar'];if($q<=0)throw new RuntimeException('Miktar geçersiz.');$m=all($pdo,'SELECT * FROM malzemeler WHERE id=? AND tenant_id=?',[$mid,tenant_id()])[0]??null;if(!$m)throw new RuntimeException('Malzeme yok.');if($m['lot_takip']&&!$lot)throw new RuntimeException('Lot zorunlu.');if($m['skt_takip']&&!$skt)throw new RuntimeException('SKT zorunlu.');$pdo->beginTransaction();$s=$pdo->prepare("SELECT id FROM stok_partileri WHERE tenant_id=? AND malzeme_id=? AND COALESCE(NULLIF(TRIM(lot_no),''),'~')=COALESCE(NULLIF(TRIM(?),''),'~') AND COALESCE(skt,'9999-12-31')=COALESCE(?,'9999-12-31') AND seri_no IS NULL LIMIT 1 FOR UPDATE");$s->execute([tenant_id(),$mid,$lot,$skt]);$pid=(int)($s->fetchColumn()?:0);if(!$pid){$i=$pdo->prepare("INSERT INTO stok_partileri(tenant_id,malzeme_id,lot_no,skt,durum) VALUES(?,?,?,?, 'SERBEST')");$i->execute([tenant_id(),$mid,$lot?:null,$skt]);$pid=(int)$pdo->lastInsertId();}$i=$pdo->prepare("INSERT INTO stok_hareketleri(tenant_id,hareket_uuid,hareket_tipi,parti_id,kaynak_depo_id,hedef_depo_id,miktar,referans_turu,aciklama,olusturan_id) VALUES(?,?,'SATIN_ALMA_GIRIS',?,NULL,? ,?,'MAL_GIRISI','Mal giriş fişi',?)");$i->execute([tenant_id(),uuid4(),$pid,$did,$q,user_id()]);$pdo->commit();flash('Mal girişi kaydedildi; aynı lot+SKT varsa mevcut partiye hareket eklendi.');header('Location:index.php?p=stock');exit;}
 if($a==='servis_kaydet'){$cid=(int)$_POST['cihaz_id'];$c=all($pdo,'SELECT kurum_id,bolum_id FROM cihazlar WHERE id=? AND tenant_id=?',[$cid,tenant_id()])[0]??null;if(!$c||!$c['kurum_id'])throw new RuntimeException('Aktif kurum cihazı seçiniz.');$no=str_pad((string)((int)val($pdo,'SELECT COALESCE(MAX(id),0)+1 FROM servis_formlari')),8,'0',STR_PAD_LEFT);$s=$pdo->prepare("INSERT INTO servis_formlari(tenant_id,form_no,cihaz_id,kurum_id,bolum_id,teknisyen_id,tip,baslangic_at,bitis_at,bildirilen_ariza,tespit_edilen_ariza,yapilan_islem,musteri_istekleri,sonuc,tamamlandi) VALUES(?,?,?,?,?,?,'ARIZA',?,?,?,?,?,?,?,1)");$s->execute([tenant_id(),$no,$cid,$c['kurum_id'],$c['bolum_id'],user_id(),$_POST['baslangic_at'],$_POST['bitis_at']?:null,$_POST['bildirilen_ariza'],$_POST['tespit_edilen_ariza'],$_POST['yapilan_islem'],$_POST['musteri_istekleri'],$_POST['sonuc']]);flash("$no numaralı servis formu kaydedildi.");header('Location:index.php?p=service');exit;}
}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();flash($e->getMessage());header('Location:index.php?p='.$p);exit;}}
$nav=['dashboard'=>'Kontrol Merkezi','inventory'=>'Envanter','maintenance'=>'Periyodik Bakım','service'=>'Teknik Servis','stock'=>'Depo & Stok'];
function head(string $t,string $s){global $p,$nav;?><!doctype html><html lang="tr"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?=h($t)?></title><link rel="stylesheet" href="assets/app.css"></head><body><div class="app"><aside class="side"><div class="brand">Serdar GÜNLÜ<small>Management System</small></div><div class="nav"><?php foreach($nav as $k=>$v):?><a class="<?=$p===$k?'a':''?>" href="?p=<?=$k?>"><?=$v?></a><?php endforeach;?><a href="logout.php">Çıkış</a></div></aside><main><header class="top"><b><?=$t?></b><span class="mut"><?=h($_SESSION['user_name']??'Kullanıcı')?> · <?=h(role())?></span></header><section class="content"><?php if(!empty($_SESSION['_flash'])):?><div class="note"><?=h($_SESSION['_flash']);unset($_SESSION['_flash'])?></div><?php endif;?><div class="head"><div><h1><?=$t?></h1><p><?=$s?></p></div><div class="date"><?=date('d.m.Y H:i')?></div></div><?php }
function foot(){?></section></main></div></body></html><?php }
if($p==='dashboard'){head('İŞ ZEKASI & KONTROL MERKEZİ','Kurum arızaları, bakım planları, cihaz sağlığı, stok riskleri ve servis lojistiği.');$tid=tenant_id();$bak=(int)val($pdo,"SELECT COUNT(*) FROM bakim_takipleri bt JOIN cihazlar c ON c.id=bt.cihaz_id WHERE c.tenant_id=? AND bt.durum IN('BEKLIYOR','GECIKTI')",[$tid]);$tot=(int)val($pdo,'SELECT COUNT(*) FROM cihazlar WHERE tenant_id=?',[$tid]);$act=(int)val($pdo,"SELECT COUNT(*) FROM cihazlar WHERE tenant_id=? AND durum='AKTIF_KURUMDA'",[$tid]);$crit=(int)val($pdo,'SELECT COUNT(*) FROM v_malzeme_stok_ozeti WHERE tenant_id=? AND kullanilabilir_stok<=kritik_stok',[$tid]);?><div class="grid kpis"><div class="card kpi"><label>KURUM ARIZALARI</label><b>0</b><small>Kurum arıza yönetimi</small></div><div class="card kpi"><label>BEKLEYEN BAKIMLAR</label><b><?=$bak?></b><small>Planlı bakım</small></div><div class="card kpi"><label>KRİTİK STOK</label><b><?=$crit?></b><small>Stok eşik kontrolü</small></div><div class="card kpi"><label>CİHAZ SAĞLIK ORANI</label><b><?=$tot?round($act/$tot*100):0?>%</b><small>Aktif <?=$act?> / Toplam <?=$tot?></small></div></div><?php $r=all($pdo,"SELECT sf.form_no,sf.created_at,k.ad kurum,c.seri_no FROM servis_formlari sf JOIN kurumlar k ON k.id=sf.kurum_id JOIN cihazlar c ON c.id=sf.cihaz_id WHERE sf.tenant_id=? ORDER BY sf.id DESC LIMIT 8",[$tid]);?><div class="section tw"><table><thead><tr><th>FORM NO</th><th>TARİH</th><th>KURUM</th><th>CİHAZ SERİ NO</th></tr></thead><tbody><?php foreach($r as $x):?><tr><td><span class="code"><?=h($x['form_no'])?></span></td><td><?=h($x['created_at'])?></td><td><?=h($x['kurum'])?></td><td><?=h($x['seri_no'])?></td></tr><?php endforeach;?></tbody></table></div><?php foot();exit;}
if($p==='inventory'){head('ENVANTER LİSTESİ','Görsel/envanter, seri no, durum-konum, kurulum/montaj ve servis/bakım geçmişi.');$r=all($pdo,"SELECT c.id,c.seri_no,c.qr_kod,c.durum,c.depo_giris_tarihi,cs.ad sinif,m.ad marka,cm.model,k.ad kurum,k.il,k.ilce,kb.ad bolum,em.montaj_tarihi,u.ad_soyad teknisyen FROM cihazlar c JOIN cihaz_modelleri cm ON cm.id=c.cihaz_modeli_id JOIN cihaz_siniflari cs ON cs.id=cm.cihaz_sinifi_id JOIN markalar m ON m.id=cm.marka_id LEFT JOIN kurumlar k ON k.id=c.kurum_id LEFT JOIN kurum_bolumleri kb ON kb.id=c.bolum_id LEFT JOIN envanter_montajlari em ON em.id=(SELECT e2.id FROM envanter_montajlari e2 WHERE e2.cihaz_id=c.id ORDER BY e2.id DESC LIMIT 1) LEFT JOIN kullanicilar u ON u.id=em.teknisyen_id WHERE c.tenant_id=? ORDER BY c.id DESC",[tenant_id()]);?><div class="tw"><table><thead><tr><th>GÖRSEL / ENVANTER BİLGİSİ</th><th>SERİ NO</th><th>DURUM & KONUM</th><th>KURULUM / MONTAJ</th><th>İŞLEMLER</th></tr></thead><tbody><?php foreach($r as $x):?><tr><td><b><?=h($x['sinif'])?></b><br><?=h($x['marka'].' '.$x['model'])?></td><td><span class="code"><?=h($x['seri_no'])?></span><br><span class="mut"><?=h($x['qr_kod'])?></span></td><td><span class="bd <?=$x['durum']==='AKTIF_KURUMDA'?'ok':'warn'?>"><?=h($x['durum'])?></span><br><?=h($x['kurum']??'Depo')?><br><span class="mut"><?=h(trim(($x['il']??'').' / '.($x['ilce']??''),' /'))?> <?=h($x['bolum']??'')?></span></td><td><?=h($x['montaj_tarihi']??'-')?><br><span class="mut"><?=h($x['teknisyen']??'')?></span></td><td><a class="btn" href="?p=service&cihaz=<?=$x['id']?>">Servis Formları</a> <a class="btn" href="?p=maintenance&cihaz=<?=$x['id']?>">Bakımlar</a></td></tr><?php endforeach;?></tbody></table></div><?php foot();exit;}
if($p==='maintenance'){head('PERİYODİK BAKIM TAKİP LİSTESİ','Kurum, cihaz-seri, periyot, planlanan bakım tarihi ve durum.');$r=all($pdo,"SELECT bt.id,k.ad kurum,k.adres,cs.ad sinif,m.ad marka,cm.model,c.seri_no,bp.ad periyot,bt.planlanan_tarih,bt.durum FROM bakim_takipleri bt JOIN cihazlar c ON c.id=bt.cihaz_id JOIN cihaz_modelleri cm ON cm.id=c.cihaz_modeli_id JOIN cihaz_siniflari cs ON cs.id=cm.cihaz_sinifi_id JOIN markalar m ON m.id=cm.marka_id LEFT JOIN kurumlar k ON k.id=c.kurum_id JOIN bakim_planlari bp ON bp.id=bt.bakim_plani_id WHERE c.tenant_id=? ORDER BY bt.planlanan_tarih",[tenant_id()]);?><div class="tw"><table><thead><tr><th>KURUM ADI</th><th>CİHAZ / SERİ NO</th><th>PERİYOT</th><th>PLANLANAN TARİH</th><th>DURUM</th><th>İŞLEM</th></tr></thead><tbody><?php foreach($r as $x):?><tr><td><b><?=h($x['kurum']??'-')?></b><br><span class="mut"><?=h($x['adres']??'')?></span></td><td><?=h($x['sinif'].' / '.$x['marka'].' '.$x['model'])?><br><span class="mut">SN: <?=h($x['seri_no'])?></span></td><td><?=h($x['periyot'])?></td><td><?=h($x['planlanan_tarih'])?></td><td><span class="bd <?=$x['durum']==='TAMAMLANDI'?'ok':'warn'?>"><?=h($x['durum'])?></span></td><td><?=$x['durum']==='BEKLIYOR'?'<a class="btn primary" href="?p=service&new=1">Bakım Yap</a>':'-'?></td></tr><?php endforeach;?></tbody></table></div><?php foot();exit;}
if($p==='service'){head('CİHAZ SERVİS & ARIZA FORMU','Kurum/cihaz, zaman, bildirilen ve tespit edilen arıza, müdahale, sonuç ve parça akışı.');if(isset($_GET['new'])){$c=all($pdo,"SELECT c.id,k.ad kurum,kb.ad bolum,m.ad marka,cm.model,c.seri_no FROM cihazlar c JOIN cihaz_modelleri cm ON cm.id=c.cihaz_modeli_id JOIN markalar m ON m.id=cm.marka_id LEFT JOIN kurumlar k ON k.id=c.kurum_id LEFT JOIN kurum_bolumleri kb ON kb.id=c.bolum_id WHERE c.tenant_id=? AND c.durum='AKTIF_KURUMDA'",[tenant_id()]);?><form class="card form" method="post"><?=csrf_field()?><input type="hidden" name="action" value="servis_kaydet"><div class="fg"><div class="f span2"><label>KURUM / CİHAZ</label><select class="input" name="cihaz_id"><?php foreach($c as $x):?><option value="<?=$x['id']?>"><?=h($x['kurum'].' / '.$x['bolum'].' / '.$x['marka'].' '.$x['model'].' / SN '.$x['seri_no'])?></option><?php endforeach;?></select></div><div class="f"><label>BAŞLANGIÇ</label><input class="input" type="datetime-local" name="baslangic_at" value="<?=date('Y-m-d\TH:i')?>"></div><div class="f"><label>BİTİŞ</label><input class="input" type="datetime-local" name="bitis_at"></div><div class="f span2"><label>BİLDİRİLEN ARIZA</label><textarea class="input" name="bildirilen_ariza"></textarea></div><div class="f span2"><label>TESPİT EDİLEN ARIZA</label><textarea class="input" name="tespit_edilen_ariza"></textarea></div><div class="f span2"><label>YAPILAN İŞLEM</label><textarea class="input" name="yapilan_islem"></textarea></div><div class="f"><label>MÜŞTERİ İSTEKLERİ</label><input class="input" name="musteri_istekleri"></div><div class="f"><label>SONUÇ</label><select class="input" name="sonuc"><option value="FAAL">Arıza Giderildi. Cihaz Faal.</option><option value="CALISMIYOR">Arıza Giderilemedi.</option><option value="PARCA_BEKLIYOR">Parça Bekleniyor.</option><option value="MERKEZE_ALINACAK">Merkeze Alınacak.</option></select></div></div><div class="note">Serviste kullanılan parçalar ana depodan doğrudan düşmez; talep → onay → rezervasyon → teslim kodu → araç deposu → kullanım akışı uygulanır.</div><button class="btn primary">Servis Formunu Tamamla & Kaydet</button></form><?php }else{$r=all($pdo,"SELECT sf.form_no,sf.baslangic_at,k.ad kurum,c.seri_no,m.ad marka,cm.model,u.ad_soyad teknisyen,sf.bildirilen_ariza,sf.tespit_edilen_ariza,sf.sonuc FROM servis_formlari sf JOIN kurumlar k ON k.id=sf.kurum_id JOIN cihazlar c ON c.id=sf.cihaz_id JOIN cihaz_modelleri cm ON cm.id=c.cihaz_modeli_id JOIN markalar m ON m.id=cm.marka_id JOIN kullanicilar u ON u.id=sf.teknisyen_id WHERE sf.tenant_id=? ORDER BY sf.id DESC",[tenant_id()]);?><div class="toolbar"><span></span><a class="btn primary" href="?p=service&new=1">Arıza Formu Gir</a></div><div class="tw"><table><thead><tr><th>FORM NO</th><th>TARİH</th><th>KURUM / CİHAZ</th><th>TEKNİSYEN</th><th>BİLDİRİLEN / TESPİT</th><th>SONUÇ</th></tr></thead><tbody><?php foreach($r as $x):?><tr><td><span class="code"><?=h($x['form_no'])?></span></td><td><?=h($x['baslangic_at'])?></td><td><b><?=h($x['kurum'])?></b><br><span class="mut"><?=h($x['marka'].' '.$x['model'].' / SN '.$x['seri_no'])?></span></td><td><?=h($x['teknisyen'])?></td><td><?=h($x['bildirilen_ariza'])?><br><span class="mut"><?=h($x['tespit_edilen_ariza'])?></span></td><td><span class="bd info"><?=h($x['sonuc'])?></span></td></tr><?php endforeach;?></tbody></table></div><?php }foot();exit;}
if($p==='stock'){head('DEPO & STOK YÖNETİMİ','Lot/SKT, FEFO, ana/alt/kurum/araç depoları ve değiştirilemez stok hareket defteri.');if(isset($_GET['giris'])){$m=all($pdo,'SELECT m.id,m.kod,m.ad,mt.ad tur FROM malzemeler m JOIN malzeme_turleri mt ON mt.id=m.tur_id WHERE m.tenant_id=? ORDER BY m.ad',[tenant_id()]);$d=all($pdo,'SELECT id,ad FROM depolar WHERE tenant_id=? AND aktif=1 ORDER BY ad',[tenant_id()]);?><form class="card form" method="post"><?=csrf_field()?><input type="hidden" name="action" value="stok_giris"><div class="fg"><div class="f span2"><label>MALZEME</label><select class="input" name="malzeme_id"><?php foreach($m as $x):?><option value="<?=$x['id']?>"><?=h($x['kod'].' — '.$x['ad'].' ('.$x['tur'].')')?></option><?php endforeach;?></select></div><div class="f"><label>HEDEF DEPO</label><select class="input" name="depo_id"><?php foreach($d as $x):?><option value="<?=$x['id']?>"><?=h($x['ad'])?></option><?php endforeach;?></select></div><div class="f"><label>MİKTAR</label><input class="input" type="number" name="miktar" step="0.001" value="1"></div><div class="f"><label>LOT NO</label><input class="input" name="lot_no"></div><div class="f"><label>SKT</label><input class="input" type="date" name="skt"></div></div><div class="note">Aynı malzeme + aynı lot + aynı SKT ise yeni parti açılmaz; yeni giriş hareketi eklenir. Aynı lot + farklı SKT ayrı parti olarak tutulur.</div><button class="btn primary">Mal Girişini Kaydet</button></form><?php }else{$r=all($pdo,'SELECT * FROM v_malzeme_stok_ozeti WHERE tenant_id=? ORDER BY ad',[tenant_id()]);?><div class="toolbar"><span></span><a class="btn primary" href="?p=stock&giris=1">Mal Girişi</a></div><div class="tw"><table><thead><tr><th>KOD</th><th>MALZEME</th><th>TÜR</th><th>KULLANILABİLİR STOK</th><th>EN YAKIN SKT</th><th>DURUM</th></tr></thead><tbody><?php foreach($r as $x):$q=(float)$x['kullanilabilir_stok'];?><tr><td><span class="code"><?=h($x['kod'])?></span></td><td><b><?=h($x['ad'])?></b></td><td><?=h($x['tur'])?></td><td><?=$q.' '.h($x['birim'])?></td><td><?=h($x['en_yakin_skt']??'-')?></td><td><span class="bd <?=$q<=(float)$x['kritik_stok']?'bad':($q<=(float)$x['min_stok']?'warn':'ok')?>"><?=$q<=(float)$x['kritik_stok']?'KRİTİK':($q<=(float)$x['min_stok']?'DÜŞÜK':'NORMAL')?></span></td></tr><?php endforeach;?></tbody></table></div><?php }foot();exit;}http_response_code(404);echo 'Sayfa bulunamadı.';